package com.fares.saveme.feature.auth.domain.usecase

import com.fares.saveme.core.network.ApiErrorCode
import com.fares.saveme.core.network.ApiResult
import com.fares.saveme.core.platform.ClientInfo
import com.fares.saveme.core.storage.DeviceIdentityStore
import com.fares.saveme.feature.auth.data.AuthRepository
import com.fares.saveme.feature.auth.data.dto.DeviceDescriptionDto
import com.fares.saveme.feature.auth.domain.SessionManager
import com.fares.saveme.feature.auth.domain.model.SignInOutcome

/**
 * Signs in from this device. [attemptSessionId] is generated by the caller once per attempt and
 * reused on retry, so a retried sign-in never creates a second session (identity.yaml signIn).
 */
class SignInUseCase(
    private val clientInfo: ClientInfo,
    private val deviceIdentity: DeviceIdentityStore,
    private val repository: AuthRepository,
    private val sessionManager: SessionManager,
) {
    suspend operator fun invoke(email: String, password: String, attemptSessionId: String): SignInOutcome {
        if (!clientInfo.liveApiSupported) return SignInOutcome.PlatformUnsupported

        val device = DeviceDescriptionDto(
            sessionId = attemptSessionId,
            deviceId = deviceIdentity.deviceId(),
            name = clientInfo.deviceName,
            platform = clientInfo.platform,
            appVersion = clientInfo.appVersion,
        )
        return when (val result = repository.signIn(email.trim(), password, device)) {
            is ApiResult.Success -> {
                sessionManager.establish(result.value)
                SignInOutcome.Success(result.value.deletionCancelled)
            }
            is ApiResult.Failure -> when (result.code) {
                ApiErrorCode.INVALID_CREDENTIALS -> SignInOutcome.InvalidCredentials
                ApiErrorCode.ACCOUNT_LOCKED -> SignInOutcome.Locked(result.retryAfterSeconds)
                ApiErrorCode.VALIDATION_FAILED -> SignInOutcome.Validation(result.problem.fieldErrors())
                ApiErrorCode.RATE_LIMITED -> SignInOutcome.RateLimited(result.retryAfterSeconds)
                ApiErrorCode.CLIENT_VERSION_UNSUPPORTED -> SignInOutcome.UpdateRequired
                else -> SignInOutcome.Error(result.code, result.problem.requestId)
            }
            ApiResult.Offline, ApiResult.Timeout -> SignInOutcome.Offline
        }
    }
}
